-- ============================================================
-- Sales & Stock ERP Mini
-- Database Schema
-- MariaDB / MySQL
-- ============================================================

CREATE DATABASE IF NOT EXISTS mini_sales_stock_erp
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_unicode_ci;

USE mini_sales_stock_erp;

-- ============================================================
-- Users (authentication)
-- ============================================================
-- Passwords are stored as bcrypt hashes generated by PHP's
-- password_hash()/password_verify(). Never store plain text.

CREATE TABLE IF NOT EXISTS users (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,

    username VARCHAR(50) NOT NULL,
    password VARCHAR(255) NOT NULL,

    is_active TINYINT(1) NOT NULL DEFAULT 1,

    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,

    PRIMARY KEY (id),

    UNIQUE KEY uk_users_username (username)
) ENGINE=InnoDB
  DEFAULT CHARSET=utf8mb4
  COLLATE=utf8mb4_unicode_ci;
